"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, type ReactNode, useEffect, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** Props for a cart button. Pass `quantity` to control it, or `defaultQuantity` to let it hold its own count. */
export type CartButtonProps = Omit<ComponentPropsWithoutRef<"div">, "children" | "onChange"> & {
  quantity?: number;
  defaultQuantity?: number;
  onQuantityChange?: (quantity: number) => void;
  /** The most one order may hold. The plus button stops here. It defaults to 99. */
  max?: number;
  /** The text of the single button shown while the count is zero. */
  label?: ReactNode;
};

type Direction = 1 | -1;

// Critically damped: the count confirms a change, so it lands without overshoot.
const ROLL_SPRING: Transition = { type: "spring", stiffness: 520, damping: 46, mass: 1 };
const ENTER: Transition = { duration: 0.2, ease: [0.165, 0.84, 0.44, 1] };
const FADE: Transition = { duration: 0.15 };
// How far each stepper button travels out from the centre when the stepper opens.
const SPREAD = 12;

// The direction travels through AnimatePresence's `custom`, because a leaving
// count keeps the props of its last render and would exit the old way.
const ROLL = {
  enter: (dir: Direction) => ({ y: `${dir * 100}%`, opacity: 0 }),
  shown: { y: 0, opacity: 1 },
  leave: (dir: Direction) => ({ y: `${-dir * 100}%`, opacity: 0 }),
};
const SWAP = {
  enter: { opacity: 0 },
  shown: { opacity: 1 },
  leave: { opacity: 0 },
};

function CartGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true" className="size-4 shrink-0">
      <path d="M1.75 1a.75.75 0 0 0 0 1.5h.9l1.5 7.2A1.75 1.75 0 0 0 5.86 11h6.03a1.75 1.75 0 0 0 1.7-1.33l1.03-4.24A.75.75 0 0 0 13.9 4.5H4.6l-.4-1.9A2 2 0 0 0 2.24 1h-.5ZM6 15a1.25 1.25 0 1 0 0-2.5A1.25 1.25 0 0 0 6 15Zm5.5 0a1.25 1.25 0 1 0 0-2.5 1.25 1.25 0 0 0 0 2.5Z" />
    </svg>
  );
}

function MinusGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true" className="size-4">
      <rect x="3" y="7.1" width="10" height="1.8" rx="0.9" />
    </svg>
  );
}

function PlusGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true" className="size-4">
      <rect x="3" y="7.1" width="10" height="1.8" rx="0.9" />
      <rect x="7.1" y="3" width="1.8" height="10" rx="0.9" />
    </svg>
  );
}

const STEP_BUTTON = cn(
  "grid size-11 shrink-0 cursor-pointer touch-manipulation place-items-center rounded-full outline-none",
  "active:scale-90 motion-safe:transition-transform motion-safe:duration-150",
  "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
  "aria-disabled:cursor-not-allowed aria-disabled:opacity-40 aria-disabled:active:scale-100",
  "hover:bg-primary-foreground/15",
);

/**
 * Adds a product to the cart, then becomes a quantity stepper in the same
 * footprint. The count rolls up when it grows and down when it shrinks, and
 * stepping back to zero returns the single button.
 */
export function CartButton({
  quantity,
  defaultQuantity = 0,
  onQuantityChange,
  max = 99,
  label = "Add to cart",
  className,
  ...groupProps
}: CartButtonProps) {
  const clamp = (next: number) => Math.min(max, Math.max(0, Math.round(next)));
  const [ownQuantity, setOwnQuantity] = useState(() => clamp(defaultQuantity));
  const count = clamp(quantity ?? ownQuantity);
  // The roll direction comes from the last count this button rendered, so a
  // parent that sets `quantity` itself still rolls the right way.
  const [shown, setShown] = useState<{ count: number; dir: Direction }>({ count, dir: 1 });
  if (shown.count !== count) setShown({ count, dir: count > shown.count ? 1 : -1 });
  // Nothing animates or is announced until the person changes the count.
  const [touched, setTouched] = useState(false);
  const reduceMotion = useReducedMotion() ?? false;
  const inCart = count > 0;

  const addRef = useRef<HTMLButtonElement>(null);
  const plusRef = useRef<HTMLButtonElement>(null);
  // The focused button unmounts when the control changes shape. Focus moves to
  // the button that took its place, so a keyboard user keeps their spot.
  const refocus = useRef(false);
  useEffect(() => {
    if (!refocus.current) return;
    refocus.current = false;
    (inCart ? plusRef : addRef).current?.focus();
  }, [inCart]);

  const change = (next: number) => {
    const clamped = clamp(next);
    if (clamped === count) return;
    setTouched(true);
    if (clamped > 0 !== inCart) refocus.current = true;
    if (quantity === undefined) setOwnQuantity(clamped);
    onQuantityChange?.(clamped);
  };

  const slideFrom = (x: number) => (touched ? { opacity: 0, x: reduceMotion ? 0 : x } : false);
  const enter = reduceMotion ? FADE : ENTER;
  let announcement = "";
  if (touched) announcement = inCart ? `${count} in cart` : "Removed from cart";

  return (
    <div
      role="group"
      {...groupProps}
      data-state={inCart ? "in-cart" : "empty"}
      className={cn(
        "relative inline-grid h-11 min-w-32 rounded-full bg-primary text-sm font-medium text-primary-foreground",
        className,
      )}
    >
      {/* The hidden label keeps the pill as wide as the single button, so the swap never moves the page. */}
      <span aria-hidden="true" className="invisible col-start-1 row-start-1 flex items-center gap-2 px-5">
        <CartGlyph />
        {label}
      </span>
      {inCart ? (
        <div className="col-start-1 row-start-1 flex items-center justify-between">
          <motion.button
            type="button"
            aria-label={count === 1 ? "Remove from cart" : "Remove one"}
            initial={slideFrom(SPREAD)}
            animate={{ opacity: 1, x: 0 }}
            transition={enter}
            onClick={() => change(count - 1)}
            className={STEP_BUTTON}
          >
            <MinusGlyph />
          </motion.button>
          <span aria-hidden="true" data-direction={shown.dir} className="relative inline-flex overflow-hidden tabular-nums">
            <AnimatePresence mode="popLayout" initial={false} custom={shown.dir}>
              <motion.span
                key={count}
                custom={shown.dir}
                variants={reduceMotion ? SWAP : ROLL}
                initial="enter"
                animate="shown"
                exit="leave"
                transition={reduceMotion ? FADE : ROLL_SPRING}
                className="inline-block"
              >
                {count}
              </motion.span>
            </AnimatePresence>
          </span>
          <motion.button
            ref={plusRef}
            type="button"
            aria-label="Add one"
            // Not `disabled`: a disabled button drops keyboard focus at the limit.
            aria-disabled={count >= max || undefined}
            initial={slideFrom(-SPREAD)}
            animate={{ opacity: 1, x: 0 }}
            transition={enter}
            onClick={() => change(count + 1)}
            className={STEP_BUTTON}
          >
            <PlusGlyph />
          </motion.button>
        </div>
      ) : (
        <motion.button
          ref={addRef}
          type="button"
          initial={touched ? { opacity: 0, scale: reduceMotion ? 1 : 0.96 } : false}
          animate={{ opacity: 1, scale: 1 }}
          transition={enter}
          onClick={() => change(1)}
          className={cn(
            "col-start-1 row-start-1 flex cursor-pointer touch-manipulation items-center justify-center gap-2 rounded-full px-5 outline-none",
            "active:scale-97 motion-safe:transition-transform motion-safe:duration-150",
            "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
          )}
        >
          <CartGlyph />
          {label}
        </motion.button>
      )}
      <span role="status" className="sr-only">
        {announcement}
      </span>
    </div>
  );
}
